    19→	// Build hierarchical tree structure
    20→	interface TreeNode {
    21→		item: ItemSummary;
    22→		children: TreeNode[];
    23→	}
    24→
    25→	function buildTree(flatItems: ItemSummary[]): TreeNode[] {
    26→		const nodeMap = new Map<string, TreeNode>();
    27→		const roots: TreeNode[] = [];
    28→
    29→		// Create nodes for all items
    30→		flatItems.forEach((item) => {
    31→			nodeMap.set(item._ulid, { item, children: [] });
    32→		});
    33→
    34→		// Build parent-child relationships
    35→		flatItems.forEach((item) => {
    36→			const node = nodeMap.get(item._ulid);
    37→			if (!node) return;
    38→
    39→			if (item.parent) {
    40→				const parentNode = nodeMap.get(item.parent);
    41→				if (parentNode) {
    42→					parentNode.children.push(node);
    43→				} else {
    44→					roots.push(node);
    45→				}
    46→			} else {
    47→				roots.push(node);
    48→			}
    49→		});
    50→
    51→		return roots;
    52→	}
