     1→<script lang="ts">
     2→	import { onMount } from 'svelte';
     3→	import { goto } from '$app/navigation';
     4→	import * as Command from '$lib/components/ui/command';
     5→	import { search } from '$lib/api';
     6→	import type { SearchResult } from '@kynetic-ai/shared';
     7→
     8→	// AC: @web-dashboard ac-23
     9→	let open = $state(false);
    10→	let query = $state('');
    11→	let results = $state<SearchResult[]>([]);
    12→	let loading = $state(false);
    13→	let debounceTimer: ReturnType<typeof setTimeout> | null = null;
    14→
    15→	// AC: @web-dashboard ac-23 - Open command palette on Cmd+K / Ctrl+K
    16→	onMount(() => {
    17→		function handleKeydown(e: KeyboardEvent) {
    18→			if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
    19→				e.preventDefault();
    20→				open = !open;
    21→			}
    22→		}
    23→
    24→		document.addEventListener('keydown', handleKeydown);
    25→		return () => {
    26→			document.removeEventListener('keydown', handleKeydown);
    27→		};
    28→	});
    29→
    30→	// AC: @web-dashboard ac-24 - Debounced search (300ms)
    31→	$effect(() => {
    32→		if (query.trim() === '') {
    33→			results = [];
    34→			loading = false;
    35→			return;
    36→		}
    37→
    38→		loading = true;
    39→		if (debounceTimer) {
    40→			clearTimeout(debounceTimer);
    41→		}
    42→
    43→		debounceTimer = setTimeout(async () => {
    44→			try {
    45→				const response = await search(query);
    46→				results = response.results;
    47→			} catch (error) {
    48→				console.error('Search failed:', error);
    49→				results = [];
    50→			} finally {
    51→				loading = false;
    52→			}
    53→		}, 300);
    54→
    55→		return () => {
    56→			if (debounceTimer) {
    57→				clearTimeout(debounceTimer);
    58→			}
    59→		};
    60→	});
    61→
    62→	// AC: @web-dashboard ac-24 - Group results by type
    63→	const groupedResults = $derived(
    64→		results.reduce(
    65→			(acc, result) => {
    66→				if (!acc[result.type]) {
    67→					acc[result.type] = [];
    68→				}
    69→				acc[result.type].push(result);
    70→				return acc;
    71→			},
    72→			{} as Record<string, SearchResult[]>
    73→		)
    74→	);
    75→
    76→	// AC: @web-dashboard ac-25 - Navigate to detail view on click
    77→	function handleSelect(result: SearchResult) {
    78→		open = false;
    79→		query = '';
    80→		results = [];
    81→
    82→		// Map type to route
    83→		const routes: Record<string, (ulid: string) => string> = {
    84→			task: (ulid) => `/tasks?selected=${ulid}`,
    85→			item: (ulid) => `/items?selected=${ulid}`,
    86→			inbox: (ulid) => `/inbox?selected=${ulid}`,
    87→			observation: (ulid) => `/observations?selected=${ulid}`,
    88→			agent: (ulid) => `/meta?selected=${ulid}`,
    89→			workflow: (ulid) => `/meta?selected=${ulid}`,
    90→			convention: (ulid) => `/meta?selected=${ulid}`
    91→		};
    92→
    93→		const route = routes[result.type]?.(result.ulid);
    94→		if (route) {
    95→			goto(route);
    96→		}
    97→	}
    98→
    99→	// Type labels for display
   100→	const typeLabels: Record<string, string> = {
   101→		task: 'Tasks',
   102→		item: 'Spec Items',
   103→		inbox: 'Inbox',
   104→		observation: 'Observations',
   105→		agent: 'Agents',
   106→		workflow: 'Workflows',
   107→		convention: 'Conventions'
   108→	};
   109→</script>
   110→
   111→<!-- AC: @web-dashboard ac-23 -->
   112→<Command.Dialog bind:open bind:value={query} title="Search" description="Search across all entities">
   113→	{@render children()}
   114→</Command.Dialog>
   115→
   116→{#snippet children()}
   117→	<!-- AC: @web-dashboard ac-23, ac-24 -->
   118→	<Command.Input placeholder="Search tasks, items, inbox..." />
   119→	<Command.List>
   120→		{#if loading}
   121→			<Command.Loading>Searching...</Command.Loading>
   122→		{:else if query.trim() && results.length === 0}
