     1→/**
     2→ * Meta API Routes
     3→ *
     4→ * REST endpoints for meta operations:
     5→ * - GET /api/meta/session - get session context
     6→ * - GET /api/meta/agents - list agents
     7→ * - GET /api/meta/workflows - list workflows
     8→ * - GET /api/meta/observations - list observations with filter
     9→ *
    10→ * AC Coverage:
    11→ * - ac-15: GET /api/meta/session returns session context
    12→ * - ac-16: GET /api/meta/agents returns all agents
    13→ * - ac-17: GET /api/meta/workflows returns all workflows
    14→ * - ac-18: GET /api/meta/observations with filter
    15→ */
    16→
    17→import { Elysia, t } from 'elysia';
    18→import {
    19→  initContext,
    20→  loadMetaContext,
    21→  loadSessionContext,
    22→} from '../../parser/index.js';
    23→import { join } from 'path';
    24→
    25→interface MetaRouteOptions {}
    26→
    27→export function createMetaRoutes(options: MetaRouteOptions = {}) {
    28→  // No closure-scoped kspecDir needed - comes from middleware
    29→
    30→  return new Elysia({ prefix: '/api/meta' })
    31→    // AC: @api-contract ac-15 - Get session context
    32→    .get('/session', async ({ projectContext }) => {
    33→      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
    34→      const kspecDir = join(projectContext.path, '.kspec');
    35→      const ctx = await initContext(kspecDir);
    36→      const session = await loadSessionContext(ctx);
    37→
    38→      // AC: @api-contract ac-15 - Return session context (focus, threads, questions)
    39→      return {
    40→        focus: session.focus,
    41→        threads: session.threads || [],
    42→        questions: session.questions || [],
    43→        updated_at: session.updated_at,
    44→      };
    45→    })
    46→
    47→    // AC: @api-contract ac-16 - List agents
    48→    .get('/agents', async ({ projectContext }) => {
    49→      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
    50→      const kspecDir = join(projectContext.path, '.kspec');
    51→      const ctx = await initContext(kspecDir);
    52→      const meta = await loadMetaContext(ctx);
    53→
    54→      // AC: @api-contract ac-16 - Return all defined agents
    55→      const agents = meta.agents;
    56→
    57→      return {
    58→        items: agents,
    59→        total: agents.length,
    60→      };
    61→    })
    62→
    63→    // AC: @api-contract ac-17 - List workflows
    64→    .get('/workflows', async ({ projectContext }) => {
    65→      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
    66→      const kspecDir = join(projectContext.path, '.kspec');
    67→      const ctx = await initContext(kspecDir);
    68→      const meta = await loadMetaContext(ctx);
    69→
    70→      // AC: @api-contract ac-17 - Return all defined workflows
    71→      const workflows = meta.workflows;
    72→
    73→      return {
    74→        items: workflows,
    75→        total: workflows.length,
    76→      };
    77→    })
    78→
    79→    // AC: @api-contract ac-18 - List observations with filter
    80→    .get(
    81→      '/observations',
    82→      async ({ query, projectContext }) => {
    83→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
    84→        const kspecDir = join(projectContext.path, '.kspec');
    85→        const ctx = await initContext(kspecDir);
    86→        const meta = await loadMetaContext(ctx);
    87→
    88→        // Start with all observations
    89→        let filtered = meta.observations || [];
    90→
    91→        // AC: @api-contract ac-18 - Filter by resolved status
    92→        if (query.resolved !== undefined) {
    93→          const resolvedFilter = query.resolved === 'true';
    94→          filtered = filtered.filter((obs) => {
    95→            const isResolved = !!obs.resolved_at;
    96→            return isResolved === resolvedFilter;
    97→          });
    98→        }
    99→
   100→        // Optional type filter (not in ACs but useful)
   101→        if (query.type) {
   102→          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
   103→          filtered = filtered.filter((obs) => typeFilters.includes(obs.type));
   104→        }
   105→
   106→        // Sort by created_at descending (newest first)
   107→        const sorted = [...filtered].sort(
   108→          (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
   109→        );
   110→
   111→        return {
   112→          items: sorted,
   113→          total: sorted.length,
   114→        };
   115→      },
   116→      {
   117→        query: t.Object({
   118→          resolved: t.Optional(t.String()),
   119→          type: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   120→        }),
   121→      }
   122→    );
   123→}
