/**
 * API Client
 *
 * Helper functions for making requests to the kspec daemon API.
 * All functions use fetch with localhost:3456 as the base URL.
 */

import type {
	TaskSummary,
	TaskDetail,
	ItemSummary,
	ItemDetail,
	InboxItem,
	SessionContext,
	Observation,
	PaginatedResponse,
	ErrorResponse,
	SearchResponse
} from '@kynetic-ai/shared';

const API_BASE = 'http://localhost:3456';

/**
 * Fetch tasks with optional filters
 * AC: @web-dashboard ac-9, ac-10
 */
export async function fetchTasks(params?: {
	status?: string;
	type?: string;
	tag?: string;
	assignee?: string;
	automation?: string;
	limit?: number;
	offset?: number;
}): Promise<PaginatedResponse<TaskSummary>> {
	const url = new URL(`${API_BASE}/api/tasks`);

	if (params) {
		Object.entries(params).forEach(([key, value]) => {
			if (value !== undefined && value !== '') {
				url.searchParams.set(key, String(value));
			}
		});
	}

	const response = await fetch(url.toString());
	if (!response.ok) {
		const error: ErrorResponse = await response.json();
		throw new Error(error.message || error.error);
	}

